def create_question(qid, order, text, subject_id, subject_name, topic_id, topic_name, diff, opt_a, opt_b, opt_c, opt_d, correct_key, expl):
    return {
        "id": qid,
        "order": order,
        "questionText": text,
        "questionType": "MCQ",
        "difficulty": diff,
        "subjectId": subject_id,
        "subjectName": subject_name,
        "topicId": topic_id,
        "topicName": topic_name,
        "marks": 1.0,
        "negativeMarks": 0.25,
        "explanation": expl,
        "options": [
            {"id": f"{qid}-a", "optionKey": "A", "optionText": opt_a, "isCorrect": correct_key == "A"},
            {"id": f"{qid}-b", "optionKey": "B", "optionText": opt_b, "isCorrect": correct_key == "B"},
            {"id": f"{qid}-c", "optionKey": "C", "optionText": opt_c, "isCorrect": correct_key == "C"},
            {"id": f"{qid}-d", "optionKey": "D", "optionText": opt_d, "isCorrect": correct_key == "D"},
        ]
    }

