for idx, item in enumerate(dbms_raw):
    qid = f"bca-dbms-q{idx+1:03d}"
    diff = "Easy" if idx < 30 else ("Moderate" if idx < 75 else "Hard")
    topic_name = "Architecture & Schema" if idx < 12 else ("Relational Model & Algebra" if idx < 25 else ("Normalization" if idx < 45 else ("SQL & Transactions" if idx < 75 else "Advanced DBMS & Recovery")))
    topic_id = f"top-dbms-{(idx // 20) + 1}"
    q = create_question(qid, idx+1, item[0], "sub-bca-501", "DBMS (BCA-501)", topic_id, topic_name, diff, item[1], item[2], item[3], item[4], item[5], item[6])
    dbms_qs.append(q)

print(f"Generated {len(dbms_qs)} DBMS questions.")
